import { NextResponse } from 'next/server';
import { put } from '@vercel/blob';
import { getCurrentUser } from '@/lib/auth';
import { audioStorageReady, authorizeAudioUpload, validateAudio, newAudioPath, audioPlaybackUrl } from '@/lib/audioStorage';
export async function POST(request: Request) {try {
 const user=await getCurrentUser();if(!user)return NextResponse.json({error:'Chưa đăng nhập'},{status:401});
 if(!audioStorageReady())return NextResponse.json({error:'Kho ghi âm chưa được cấu hình.'},{status:503});
 if(request.headers.get('content-type')?.includes('application/json')) {
 const body=await request.json();const mime=validateAudio(String(body.mimeType||''),Number(body.size));const assignmentId=body.assignmentId||null;
 await authorizeAudioUpload(user,assignmentId);return NextResponse.json({pathname:newAudioPath(user.id,mime,assignmentId)});
 }
 if(Number(request.headers.get('content-length'))>4*1024*1024)return NextResponse.json({error:'Tệp lớn cần tải trực tiếp vào kho.'},{status:413});
 const form=await request.formData();const file=form.get('audio');
 if(!file||typeof file==='string')return NextResponse.json({error:'Thiếu bản ghi.'},{status:400});
 const mime=validateAudio(file.type,file.size);if(file.size>3*1024*1024)return NextResponse.json({error:'Tệp lớn cần tải trực tiếp vào kho.'},{status:413});
 const assignmentId=String(form.get('assignmentId')||'')||null;await authorizeAudioUpload(user,assignmentId);
 const blob=await put(newAudioPath(user.id,mime,assignmentId),file,{access:'private',contentType:mime,addRandomSuffix:false,allowOverwrite:false});
 return NextResponse.json({success:true,url:audioPlaybackUrl(blob.pathname),size:file.size,mimeType:mime});
 }catch(error:any){return NextResponse.json({error:error.message||'Tải ghi âm thất bại.'},{status:error.status||500});}}

import { NextResponse } from 'next/server';
import { handleUpload, type HandleUploadBody } from '@vercel/blob/client';
import { getCurrentUser } from '@/lib/auth';
import { audioStorageReady,parseAudioPath,authorizeAudioUpload,MAX_AUDIO_SIZE,AUDIO_TYPES } from '@/lib/audioStorage';
export async function POST(request: Request) {try {
 if(!audioStorageReady())return NextResponse.json({error:'Kho ghi âm chưa được cấu hình.'},{status:503});
 const body=await request.json() as HandleUploadBody;
 const result=await handleUpload({request,body,onBeforeGenerateToken:async pathname=>{
 const user=await getCurrentUser();if(!user)throw Object.assign(new Error('Chưa đăng nhập'),{status:401});
 const scope=parseAudioPath(pathname);if(scope.ownerId!==user.id)throw Object.assign(new Error('Bản ghi không thuộc bạn.'),{status:403});
 await authorizeAudioUpload(user,scope.assignmentId);
 return {allowedContentTypes:AUDIO_TYPES,maximumSizeInBytes:MAX_AUDIO_SIZE,addRandomSuffix:false,allowOverwrite:false,validUntil:Date.now()+10*60*1000};
 }});return NextResponse.json(result);
 }catch(error:any){return NextResponse.json({error:error.message||'Không cấp được quyền tải ghi âm.'},{status:error.status||400});}}

import { NextResponse } from 'next/server';
import { get } from '@vercel/blob';
import { getCurrentUser } from '@/lib/auth';
import { authorizeAudioRead } from '@/lib/audioStorage';
export const dynamic='force-dynamic';
export async function GET(request: Request) {try {
 const user=await getCurrentUser();if(!user)return NextResponse.json({error:'Chưa đăng nhập'},{status:401});
 const pathname=new URL(request.url).searchParams.get('pathname')||'';await authorizeAudioRead(user,pathname);
 const range=request.headers.get('range');if(range&&!/^bytes=\d*-\d*$/.test(range))return new Response(null,{status:416});
 const result=await get(pathname,{access:'private',headers:range?{Range:range}:undefined,abortSignal:request.signal});
 if(!result||result.statusCode!==200)return new Response(null,{status:404});
 const headers=new Headers({'Content-Type':result.blob.contentType,'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','Accept-Ranges':'bytes'});
 for(const key of ['content-length','content-range']){const value=result.headers.get(key);if(value)headers.set(key,value);}
 return new Response(result.stream,{status:result.headers.has('content-range')?206:200,headers});
 }catch(error:any){return NextResponse.json({error:error.status?'Không có quyền truy cập bản ghi.':'Không tải được bản ghi.'},{status:error.status||502});}}

