const {test}=require('node:test'),assert=require('node:assert/strict');const {load}=require('./ability-test-loader.cjs');
const filename='12345678-1234-1234-1234-123456789abc.webm';const path='audio/student/assignments/a1/'+filename;const url='/api/audio/play?pathname='+encodeURIComponent(path);
function fixture(){let teacher='teacher',closed=false,submission='draft';const calls=[];const db={assignment:{findUnique:async()=>({skill:'speaking',status:closed?'closed':'published',classroom:{members:[{studentId:'student'}]}})},submission:{findFirst:async args=>{calls.push(args);if(args.select?.status)return submission?{status:submission}:null;return args.where.assignment?.classroom?.teacherId===teacher&&args.where.audioUrl===url?{id:'s1'}:null;}}};const sdk={head:async pathname=>{calls.push(pathname);return{contentType:'audio/webm',size:1500};},get:async(pathname,opts)=>{calls.push({pathname,opts});return{statusCode:200,stream:new ReadableStream({start(c){c.enqueue(new Uint8Array([1,2,3]));c.close();}}),blob:{contentType:'audio/webm'},headers:new Headers(opts.headers?{'content-range':'bytes 0-2/1500','content-length':'3'}:{'content-length':'3'})};},put:async(pathname,file,options)=>{calls.push(options);return{pathname};}};const helper=load('lib/audioStorage.ts',{'./prisma':{__esModule:true,default:db},'@vercel/blob':sdk,crypto:require('crypto')});return{helper,calls,sdk,close:()=>closed=true,submit:()=>submission='pending_grading'};}
test('path parsing rejects arbitrary URLs, traversal, wrong owner/scope; URL canonical roundtrip',()=>{const {helper:h}=fixture();assert.deepEqual(h.parseAudioPath(path),{ownerId:'student',assignmentId:'a1'});assert.equal(h.audioPathFromUrl(url),path);for(const p of ['https://evil.invalid/audio','../audio/student',path.replace('student','..'),path+'?x=1'])assert.throws(()=>h.parseAudioPath(p));for(const u of ['blob:abc','https://evil.invalid/x','/uploads/audio/old.webm',url+'&x=1'])assert.throws(()=>h.audioPathFromUrl(u));});
test('audio sizes/MIME validation includes mobile MP4/OGG and blocks forged type/empty/large',()=>{const h=fixture().helper;assert.equal(h.validateAudio('audio/webm;codecs=opus',500),'audio/webm');assert.equal(h.validateAudio('audio/mp4',800),'audio/mp4');assert.equal(h.validateAudio('audio/ogg',800),'audio/ogg');for(const [type,size] of [['text/html',800],['audio/webm',499],['audio/mp4',20*1024*1024+1]])assert.throws(()=>h.validateAudio(type,size));});
