test('private playback route authenticates, streams ranges and sets no-store',async()=>{const f=fixture();let user={id:'teacher',role:'teacher'};const route=load('app/api/audio/play/route.ts',{'next/server':{NextResponse:{json:(body,options)=>Response.json(body,options)}},'@vercel/blob':f.sdk,'@/lib/auth':{getCurrentUser:async()=>user},'@/lib/audioStorage':f.helper});let res=await route.GET(new Request('http://local'+url,{headers:{Range:'bytes=0-2'}}));assert.equal(res.status,206);assert.equal(res.headers.get('cache-control'),'private, no-store');assert.equal(res.headers.get('content-range'),'bytes 0-2/1500');assert.equal((await res.arrayBuffer()).byteLength,3);user={id:'outsider',role:'teacher'};assert.equal((await route.GET(new Request('http://local'+url))).status,403);user=null;assert.equal((await route.GET(new Request('http://local'+url))).status,401);});
